const fixed={type:'answer',records:[{name:'example.com',type:'A',ttl:60,rdata:{A:{addr:'192.0.2.8'}}}]};
const group=actions=>({order:0,rules:[{actions}]});
const tls={transport:'tls',address:'resolver.example',port:853};
const upstream={type:'queryUpstream',upstream:'primary'};
const https={transport:'https',url:'https://dns.quad9.net/dns-query'};
const configs={fixed:{DNS_RULE_MAIN:group([fixed])},https:{DNS_UPSTREAMS:{primary:https},DNS_RULE_MAIN:group([upstream])},tcp:{DNS_UPSTREAMS:{primary:{transport:'tcp',address:'9.9.9.9',port:53}},DNS_RULE_MAIN:group([upstream])},'tls-unused':{DNS_UPSTREAMS:{unused:tls},DNS_RULE_MAIN:group([fixed,{type:'return'}])},'tls-optional':{DNS_UPSTREAMS:{primary:tls},DNS_RULE_MAIN:group([fixed,{...upstream,onError:'continue'}])},'tls-unreachable':{DNS_UPSTREAMS:{primary:tls},DNS_RULE_MAIN:{order:0,rules:[{when:{field:'query.type',op:'eq',value:'AAAA'},actions:[upstream]},{actions:[fixed]}]}},'tls-mixed':{DNS_UPSTREAMS:{primary:https,unused:tls},DNS_RULE_MAIN:group([upstream])},'tcp-identity':{DNS_UPSTREAMS:{primary:{transport:'tcp',address:'9.9.9.9',serverName:'resolver.example'}},DNS_RULE_MAIN:group([upstream])},empty:{}};
