{scenario:'fixed',rcode:0,fixed:true},{scenario:'fixed',method:'GET',rcode:0,fixed:true},{scenario:'fixed',json:true,rcode:0,fixed:true},
{scenario:'https',rcode:0,upstream:true},{scenario:'tcp',rcode:0,upstream:true},
...['tls-unused','tls-optional','tls-unreachable','tls-mixed','tcp-identity'].map(scenario=>({scenario,rcode:2,failure:'INVALID_CONFIG'})),
{scenario:'empty',rcode:2,failure:'NO_RESPONSE'},{scenario:'fixed',json:true,duplicate:true,status:400}];
