const response=await fetch(url,{method,headers,body:method==='POST'?wire:undefined,redirect:'manual',signal:AbortSignal.timeout(15000)});sample.httpStatus=response.status;sample.sourceSha=response.headers.get('x-release-source');sample.version=response.headers.get('x-release-version');sample.sampleEcho=response.headers.get('x-release-sample');sample.failures=response.headers.get('x-release-failures');assert.equal(sample.sourceSha,expectedSha);assert.equal(sample.version,expectedVersion);assert.equal(sample.sampleEcho,sample.id);assert.equal(response.status,c.status??200);assert.equal(response.headers.get('cache-control'),'no-store');assert.equal(sample.failures,c.failure??(c.status?'INVALID_HTTP':''));
const bytes=new Uint8Array(await response.arrayBuffer());assert.ok(bytes.length<=65535);assert.equal(response.headers.get('content-type')?.split(';')[0],c.json?'application/dns-json':'application/dns-message');
if(c.json){const body=JSON.parse(Buffer.from(bytes).toString());if(c.status){assert.ok(body.error);sample.errorCode=body.error.code;}else{assert.equal(body.Status,c.rcode);assert.equal(body.Answer.length,1);assert.equal(body.Answer[0].data,'192.0.2.8');assert.equal(body.Answer[0].TTL,60);assert.equal(body.AD,false);sample.rcode=body.Status;sample.answerCount=body.Answer.length;}}
else{const result=decode(bytes);assert.equal(result.id,0x4242);assert.ok(result.flags&0x8000);assert.equal(result.flags&0x0200,0);assert.deepEqual(result.questions,[{name:'example.com',type:1,class:1}]);sample.rcode=result.flags&15;assert.equal(sample.rcode,c.rcode);sample.answerCount=result.records.filter(r=>r.section===0).length;if(c.fixed){assert.equal(result.records.length,1);assert.deepEqual(result.records[0],{name:'example.com',type:1,ttl:60,section:0,data:[192,0,2,8]});assert.equal(result.flags&0x20,0);}if(c.upstream){assert.ok(sample.answerCount>0);assert.ok(result.records.some(r=>r.section===0&&r.type===1&&r.data.length===4));}if(c.rcode===2)assert.equal(result.records.length,0);}
sample.correct=true;if(phase==='baseline')sample.newTlsRejectionContractSatisfied=false;
}catch(e){sample.error={name:e.name,message:e.message};}finally{sample.finishedAt=new Date().toISOString();fs.writeFileSync(ledgerPath,JSON.stringify(ledger,null,2));console.log(JSON.stringify(sample));}}
assert.ok(ledger.filter(s=>s.phase===phase).every(s=>s.correct),'Cloud smoke assertions failed; preserve ledger and clean up without retries.');

